  // For bites, create a postback similar to the drink format but with NONE for size and add-on
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Adding to cart...`,
      senderId,
      isBitesSelected: true,
      // Create postback in the same format as drinks but with NONE values
      postback: `${product.ProductID}|NONE|NONE`,
      type: "postback"
    }
  }];
}

const sizes = Array.isArray(product.Sizes) ? product.Sizes : [];

if (sizes.length === 0) {
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Added to cart!`,
