const allInputs = $input.all();
const validationResult = allInputs[0].json;

if (!validationResult.isValid) {
  return {
    json: {
      success: false,
      message: "Cannot add to cart due to validation errors",
      errors: validationResult.errors,
      warnings: validationResult.warnings
    }
  };
}

const { productData, addOnData } = validationResult;
const stockData = allInputs[0].json.stockCheckData || validationResult.stockCheckData;
const ingredientData = stockData.ingredientData;

// Determine if this is a bite item (has direct BasePrice) or drink item (has Sizes array with prices)
const isBite = productData.ProductID.startsWith('BK-');
const basePrice = isBite ? productData.BasePrice : 
                 (productData.Sizes && productData.Sizes.length > 0 ? productData.Sizes[0].BasePrice : 0);

const cartItem = {
  productId: productData.ProductID,
  productName: productData.Name,
  category: productData.Category,
  basePrice: basePrice,
  // Only include size for drink items, not for bites
  size: isBite ? null : (productData.Sizes[0]?.Size || "16oz"),
  quantity: 1,
  addOns: [
    ...(addOnData ? [{
      addOnId: addOnData.AddOnID,
      addOnName: addOnData.Name,
      addOnPrice: addOnData.BasePrice,
      quantity: 1
    }] : []),
    ...(ingredientData ? [{
      ingredientId: ingredientData.IngredientID,
      ingredientName: ingredientData.Name,
      ingredientPrice: 15, // Fixed price for ingredients
      quantity: 1
    }] : [])
  ],
  totalPrice: basePrice + (addOnData ? addOnData.BasePrice : 0) + (ingredientData ? 15 : 0),
  timestamp: new Date().toISOString(),
  userId: $('Listen').first().json.senderId
};

return {
  json: {
    success: true,
    message: "Item successfully added to cart",
    cartItem: cartItem,
    warnings: validationResult.warnings
  }
};

const userId = $('Listen').first().json.senderId;
const cartItem = $input.first().json.cartItem;

return {
  json: {
    userId: userId,
    cartItem: cartItem
  }
};

const data = $('Upsert Prepare').first().json;
const now = new Date().toISOString();

return {
  json: {
    userId: data.userId,
    items: [data.cartItem], // Create a new items array with the first item
    createdAt: now,
    updatedAt: now
  }
};

const newItemData = $('Upsert Prepare').first().json;


const existingCart = $('Add to Cart DB').first().json;

const updatedItems = [...existingCart.items, newItemData.cartItem];

return {
  json: {
    userId: existingCart.userId,
    items: updatedItems,
    updatedAt: new Date().toISOString()
  }
};

