let errors = [];
let warnings = [];

// Check if product is available and enabled
if (productData && (!productData.isEnabled && !productData.available)) {
  errors.push(`${productData.Name} is not available at this time. Please select another item.`);
}

// BITES HANDLING: Direct check for bites items
if (productData && productData.ProductID && productData.ProductID.startsWith('BK-')) {
  if (productData.Quantity <= 0) {
    errors.push(`${productData.Name} is currently out of stock. Please select another item.`);
  } else if (productData.Quantity <= 5) {
    warnings.push(`Stock for ${productData.Name} is low (${productData.Quantity} remaining).`);
  }
}

// Check add-on quantity
if (addOnData) {
  if (!addOnData.isEnabled) {  // Fixed: changed IsEnabled to isEnabled
    errors.push(`The add-on ${addOnData.Name} is not available at this time. Please select another option.`);
  } else if (addOnData.Quantity <= 0) {
    errors.push(`The add-on ${addOnData.Name} is out of stock. Please select an alternative.`);
  } else if (addOnData.Quantity <= 3) {
    warnings.push(`Stock for add-on ${addOnData.Name} is low (${addOnData.Quantity} remaining).`);
  }
}

// Check ingredients for non-bites items
if (Object.keys(requiredIngredients).length > 0) {
  Object.entries(requiredIngredients).forEach(([ingredientId, required]) => {
    const ingredient = inventoryData.find(inv => inv.json.IngredientID === ingredientId);
    if (!ingredient) {
      errors.push(`An ingredient required for your order could not be found in our inventory. Please select another item.`);
    } else if (!ingredient.json.isEnabled) { // <-- fixed here
      errors.push(`One of the ingredients required for your order is currently unavailable. Please select another item.`);
    } else if (ingredient.json.Quantity < required) {
      errors.push(`We do not have enough stock of an ingredient to fulfill your order. Please select another item.`);
    } else if (ingredient.json.Quantity <= 5) {
      warnings.push(`Some ingredients for your order are running low (${ingredient.json.Quantity} remaining).`);
    }
  });
}

