      item.addOns.forEach(newAddon => {
        const newAddonName = newAddon.ingredientName || newAddon.addOnName;
        const existingAddon = groupedItems[key].addOns.find(addon => (addon.ingredientName || addon.addOnName) === newAddonName);
        if (existingAddon) existingAddon.quantity += newAddon.quantity;
        else groupedItems[key].addOns.push({...newAddon});
      });
    }
  } else {
    groupedItems[key] = {
      productName: item.productName,
      category: item.category,
      size: item.size,
      quantity: item.quantity || 1,
      basePrice: item.basePrice,
      totalPrice: item.totalPrice,
      addOns: item.addOns ? [...item.addOns] : []
    };
  }
});

Object.values(groupedItems).forEach(item => {
  const displaySize = (item.category === "Pastries" || !item.size) ? "" : ` (${item.size})`;
  cartMessage += `${item.productName}${displaySize}\n`;
  const baseTotal = (item.basePrice * item.quantity);
  const baseTotalStr = `₱${baseTotal.toFixed(2)}`.padStart(8, ' ');
  cartMessage += `- ${item.quantity} X ₱${item.basePrice.toFixed(2)} = ${baseTotalStr}\n`;
  if (item.addOns && item.addOns.length > 0) {
    item.addOns.forEach(addon => {
      const addonName = addon.ingredientName || addon.addOnName;
      const addonPrice = addon.ingredientPrice || addon.addOnPrice || 0;
      const addonTotal = (addonPrice * addon.quantity);
      const addonTotalStr = `₱${addonTotal.toFixed(2)}`.padStart(8, ' ');
      cartMessage += `${addonName}\n`;
      cartMessage += `- ${addon.quantity} X ₱${addonPrice.toFixed(2)} = ${addonTotalStr}\n`;
    });
  }
  cartMessage += "\n";
});

const calculatedSubtotal = Object.values(groupedItems).reduce((sum, item) => sum + item.totalPrice, 0);
const subtotalStr = `₱${calculatedSubtotal.toFixed(2)}`.padStart(8, ' ');
cartMessage += `---------------\n`;
cartMessage += `Subtotal: ${subtotalStr}\n\n`;
if (applicablePromos.length > 0) {
  cartMessage += "🎉 Great news! You have redeemable promos available for your cart items! Swipe left to apply.\n\n";
}
cartMessage += "Delivery fee will be calculated at checkout\n\n";

// Build quick replies (existing + new promo ones)
const quickReplies = [
  { content_type: "text", title: "Proceed to Checkout", payload: "CHECKOUT" },
  { content_type: "text", title: "Continue Shopping", payload: "REVIEW_MENU" },
  { content_type: "text", title: "Clear Cart", payload: "CLEAR_CART" }
];

// Add promo quick replies
applicablePromos.forEach(promo => {
  quickReplies.push({
    content_type: "text",
    title: `Apply ${promo.discountPercentage}% Promo`,
    payload: `APPLY_PROMO_${promo._id}`
  });
});

const messageObject = {
  messaging_type: "RESPONSE",
  recipient: { id: senderId },
  message: {
    text: cartMessage,
    quick_replies: quickReplies
  }
};

return { json: messageObject };
